// BEFORE: borrows request state into spawned work, one shared queue,
// ack before store, no trace or dedupe key.
async fn handle(req: Request) {
    tokio::spawn(async move {
        // req is owned by this 'static task, so this borrow compiles. The bug
        // is the design: body is a &[u8] into the moved req, so the broker
        // publishes a bare borrowed slice instead of an owned envelope.
        let body = &req.body;
        broker.publish("tasks", body).await;  // one queue for everything
    });
}
