use std::collections::HashMap;
use std::sync::Mutex;

// Durable owner of finish-once state, keyed by idempotency key.
// Put-if-absent makes a redelivery a no-op.
struct CompletionStore {
    done: Mutex<HashMap<String, u64>>, // task_id -> result
}

impl CompletionStore {
    // Returns true when this result matches the stored entry (the common
    // idempotent-replay case); returns false only when a prior call stored a
    // different result. It does NOT distinguish the first writer from a replay,
    // so a side effect must never be gated on this return value. Detecting the
    // first writer requires an atomic put-if-absent / compare-and-set in the
    // real store.
    fn complete_once(&self, task_id: &str, result: u64) -> bool {
        let mut g = self.done.lock().unwrap();
        g.entry(task_id.to_string()).or_insert(result);
        // The stored value is whatever the first writer set; report whether
        // this call's result agrees with it.
        g.get(task_id) == Some(&result)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use std::thread;

    #[test]
    fn redelivery_completes_exactly_once() {
        let store = CompletionStore { done: Mutex::new(HashMap::new()) };
        // first delivery completes; redelivery must not duplicate.
        store.complete_once("task-7", 42);
        let r2 = store.complete_once("task-7", 42); // lease-expiry replay
        assert_eq!(r2, true, "replay with same result returns true, not false");
        assert_eq!(store.done.lock().unwrap().len(), 1);
    }

    #[test]
    fn racing_deliveries_complete_exactly_once() {
        let store = Arc::new(CompletionStore { done: Mutex::new(HashMap::new()) });
        let a = Arc::clone(&store);
        let b = Arc::clone(&store);
        // Two concurrent deliveries of the same task must collapse to one entry.
        let h1 = thread::spawn(move || a.complete_once("task-7", 42));
        let h2 = thread::spawn(move || b.complete_once("task-7", 42));
        h1.join().unwrap();
        h2.join().unwrap();
        assert_eq!(store.done.lock().unwrap().len(), 1);
    }
}

