// Verified dispatcher: only verified tasks run, and each task is routed to the
// broker key for its workload class. The verification gate sits BEFORE the
// route is recorded, so an unverified task is never dispatched.
#[derive(Debug, Clone, Copy)]
enum Workload {
    Graph,
    Matrix,
}

#[derive(Debug, Clone, Copy)]
struct TaskEnvelope {
    task_id: &'static str,
    verified: bool,
    workload: Workload,
}

// Route names the workload class so graph and matrix work land on separate
// broker keys (and later, separate queues).
fn route(task: &TaskEnvelope) -> &'static str {
    match task.workload {
        Workload::Graph => "tasks.graph",
        Workload::Matrix => "tasks.matrix",
    }
}

// The control-path gate: a task runs only when its input was verified.
fn should_run(task: &TaskEnvelope) -> bool {
    task.verified
}

fn main() {
    let tasks = [
        TaskEnvelope {
            task_id: "graph-1",
            verified: true,
            workload: Workload::Graph,
        },
        TaskEnvelope {
            task_id: "matrix-1",
            verified: true,
            workload: Workload::Matrix,
        },
        TaskEnvelope {
            task_id: "reject-1",
            verified: false,
            workload: Workload::Graph,
        },
    ];

    let mut accepted = 0_u32;
    let mut rejected = 0_u32;
    let mut last_route = "none";

    for task in tasks {
        if should_run(&task) {
            accepted += 1;
            last_route = route(&task);
        } else {
            rejected += 1;
        }
    }

    println!("accepted = {}", accepted);
    println!("rejected = {}", rejected);
    println!("last route = {}", last_route);
}
